#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path.cwd()
source = root / "src" / "MacSrc" / "SDLSound.c"
output = root / "src" / "MacSrc" / "SDLSound_3DS_V12C.c"

if not source.is_file():
    print(
        "ERROR: src/MacSrc/SDLSound.c was not found. "
        "Run this script from the Shockolate project root.",
        file=sys.stderr,
    )
    raise SystemExit(1)

text = source.read_text(encoding="utf-8")

if "PROJECT CITADEL SDLSOUND V12C" in text:
    print("ERROR: SDLSound.c already contains V12C.", file=sys.stderr)
    raise SystemExit(1)

if "PROJECT CITADEL SDLSOUND V12B" in text:
    print(
        "ERROR: This is the V12B-patched SDLSound.c. "
        "Restore SDLSound_before_3ds_V12B.c first.",
        file=sys.stderr,
    )
    raise SystemExit(1)

comment = "// Sound stubs that do nothing, when SDL Mixer is not found"
comment_pos = text.find(comment)
if comment_pos < 0:
    print(
        "ERROR: Could not locate the clean ENABLE_SOUND=OFF stub branch.",
        file=sys.stderr,
    )
    raise SystemExit(1)

branch_start = text.rfind("#else", 0, comment_pos)
branch_end = text.find("#endif", comment_pos)

if branch_start < 0 or branch_end < 0:
    print("ERROR: Could not locate stub branch boundaries.", file=sys.stderr)
    raise SystemExit(1)

branch_end += len("#endif")
